// -------------------------------------------------------
// Ce node extrait l'ID YouTube depuis l'URL.
// Exemple : https://www.youtube.com/watch?v=dQw4w9WgXcQ
//           → short_id = "dQw4w9WgXcQ"
// L'ID sera utilisé comme identifiant unique dans tout le pipeline.
// -------------------------------------------------------

// Récupérer l'URL depuis le webhook
const youtubeUrl = $('Webhook Trigger').item.json.youtube_url;

// Regex pour extraire l'ID depuis les formats d'URL courants :
// - youtube.com/watch?v=ID
// - youtu.be/ID
// - youtube.com/shorts/ID
const regex = /(?:youtube\.com\/(?:watch\?v=|shorts\/)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
const match = youtubeUrl.match(regex);

// Si l'URL n'est pas reconnue, on stoppe avec une erreur claire
if (!match) {
  throw new Error(`URL YouTube invalide : ${youtubeUrl}`);
}

const shortId = match[1]; // L'ID fait toujours 11 caractères

console.log(`[EXTRACT_ID] URL : ${youtubeUrl} → ID : ${shortId}`);

// Renvoyer les données enrichies au node suivant
return [{ json: { youtube_url: youtubeUrl, short_id: shortId } }];

// -------------------------------------------------------
// Ce node fusionne les données des étapes précédentes
// en un seul objet JSON pour l'upload R2.
// Il accède aux sorties des nodes précédents par leur nom.
// -------------------------------------------------------

// Données du téléchargement (node HTTP: Download + Audio)
const dl = $('HTTP: Download + Audio').item.json;

// Données de la transcription (node HTTP: Transcription Whisper)
const tr = $('HTTP: Transcription Whisper').item.json;

// URL d'origine (node webhook)
const youtubeUrl = $('Webhook Trigger').item.json.youtube_url;

console.log(`[MERGE] Fusion pour short_id=${dl.short_id} : titre='${dl.title}'`);

// Construire l'objet fusionné pour l'upload R2
return [{
  json: {
    short_id:        dl.short_id,
    youtube_url:     youtubeUrl,
    title:           dl.title,
    duration_s:      dl.duration_s,
    video_path:      dl.video_path,
    audio_path:      dl.audio_path,
    transcript_path: tr.transcript_path,
    word_count:      tr.word_count,
  }
}];

// -------------------------------------------------------
// Prépare toutes les données pour l'INSERT Postgres.
// On récupère les infos de chaque étape précédente.
// -------------------------------------------------------

const dl  = $('HTTP: Download + Audio').item.json;
const r2  = $('HTTP: Upload R2').item.json;

console.log(`[PREPARE_INSERT] short_id=${dl.short_id}, r2_video=${r2.r2_video_url}`);

return [{
  json: {
    youtube_url:         dl.youtube_url,
    title:               dl.title,
    duration_s:          dl.duration_s,
    r2_video_path:       r2.r2_video_key,
    r2_transcript_path:  r2.r2_transcript_key,
    short_id:            dl.short_id,
    r2_video_url:        r2.r2_video_url,
    r2_transcript_url:   r2.r2_transcript_url,
  }
}];
